head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 원본 dataList 의 필터를 초기화한 뒤, value 가 AA11 / AA21 / BB11 / BB21 인 행만 남도록 필터를 적용한다
// (각 버튼이 단독으로 동작하도록 모든 핸들러 선두에서 호출한다)
scwin.applyOrgFilter = function () {
    var objOrg = $p.getComponentById("gdl_org");
    objOrg.clearFilter();
    objOrg.setColumnFilter({ type: "row", colIndex: "value", key: "AA11", condition: "and" });
    objOrg.setColumnFilter({ type: "row", colIndex: "value", key: "AA21", condition: "or" });
    objOrg.setColumnFilter({ type: "row", colIndex: "value", key: "BB11", condition: "or" });
    objOrg.setColumnFilter({ type: "row", colIndex: "value", key: "BB21", condition: "or" });

    // 링크 조건 'cat1==ref("data:gdl_org.cat1")' 이 참조하는 원본 Row 를 첫 번째 Row(cat1 = A)로 맞춘다
    objOrg.setRowPosition(0);

    return objOrg;
};

// JSON 배열을 '[순번] cat1 / cat2 / value' 형식 한 줄로 만든다
scwin.jsonToLine = function (arrJson) {
    var arrText = [];
    for (var i = 0; i < arrJson.length; i++) {
        arrText.push("[" + i + "] " + arrJson[i].cat1 + " / " + arrJson[i].cat2 + " / " + arrJson[i].value);
    }
    return arrText.join("   ");
};

// XML 의 map 노드에서 하위 태그 값을 읽는다
scwin.getNodeText = function (objMap, strTag) {
    var arrNode = objMap.getElementsByTagName(strTag);
    if (arrNode.length === 0) {
        return "(없음)";
    }
    return arrNode[0].textContent;
};

// XMLDocument 를 '[index=n] cat1 / cat2 / value' 형식 한 줄로 만든다
scwin.xmlToLine = function (objXml) {
    var arrMap = objXml.getElementsByTagName("map");
    var arrText = [];
    for (var i = 0; i < arrMap.length; i++) {
        arrText.push("[index=" + arrMap[i].getAttribute("index") + "] "
            + scwin.getNodeText(arrMap[i], "cat1") + " / "
            + scwin.getNodeText(arrMap[i], "cat2") + " / "
            + scwin.getNodeText(arrMap[i], "value"));
    }
    return arrText.join("   ");
};

// 원본 dataList 에 필터만 적용하고 남은 행을 출력한다
scwin.btn_applyFilter_onclick = function (e) {
    var objOrg = scwin.applyOrgFilter();
    scwin.setReturnValue("[원본 필터 적용] gdl_org 조회 행 (cat1 / cat2 / value) : " + scwin.jsonToLine(objOrg.getAllFilteredJSON()));
};

// getAllXML() 과 getAllJSON() 의 반환값을 나란히 출력한다
scwin.btn_getAllXML_onclick = function (e) {
    scwin.applyOrgFilter();

    var objLinked = $p.getComponentById("target1");
    var objXml = objLinked.getAllXML();

    scwin.setReturnValue("[getAllJSON() - 정상 기준] (cat1 / cat2 / value) : " + scwin.jsonToLine(objLinked.getAllJSON()));
    scwin.setReturnValue("[getAllXML()  - 비교 대상] (cat1 / cat2 / value) : " + scwin.xmlToLine(objXml));
    scwin.setReturnValue("[getAllXML() 원문] " + (new XMLSerializer()).serializeToString(objXml));
};

// getAllFilteredXML() 과 getAllFilteredJSON() 의 반환값을 나란히 출력한다
scwin.btn_getAllFilteredXML_onclick = function (e) {
    scwin.applyOrgFilter();

    var objLinked = $p.getComponentById("target1");
    var objXml = objLinked.getAllFilteredXML();

    scwin.setReturnValue("[getAllFilteredJSON() - 정상 기준] (cat1 / cat2 / value) : " + scwin.jsonToLine(objLinked.getAllFilteredJSON()));
    scwin.setReturnValue("[getAllFilteredXML()  - 비교 대상] (cat1 / cat2 / value) : " + scwin.xmlToLine(objXml));
    scwin.setReturnValue("[getAllFilteredXML() 원문] " + (new XMLSerializer()).serializeToString(objXml));
};
